<div class="grid gap-5 md:grid-cols-2"><x-ui.select name="recovery_program_id" label="Programme" :value="$item->recovery_program_id" :options="$programs->mapWithKeys(fn($x)=>[$x->id=>$x->name.' · '.$x->organization_name])" required/><x-ui.input name="name" label="Nom du point" :value="$item->name" required/><x-ui.input name="address" label="Adresse" :value="$item->address" required/><x-ui.input name="city" label="Ville" :value="$item->city" required/><x-ui.input name="latitude" label="Latitude" type="number" :value="$item->latitude" step="0.0000001"/><x-ui.input name="longitude" label="Longitude" type="number" :value="$item->longitude" step="0.0000001"/><x-ui.input name="opening_hours" label="Horaires" :value="$item->opening_hours"/><div class="md:col-span-2"><x-ui.checkbox name="is_active" label="Point actif" :checked="$item->exists ? $item->is_active : true"/></div></div>
